/*
【算法說明】
本題要求計算兩個概率：
1. 在 N 次取出中，至少有一次兩個球都是紅色的概率。
   第 k 次取出時，第一個甕有 k 個球（1 紅 k-1 白），第二個甕有 k+1 個球（1 紅 k 白）。
   因此第 k 次取出兩個紅球的概率為 P_k = 1 / (k * (k + 1))。
   在 N 次中至少有一次兩紅的概率 = 1 - (所有次都不是兩紅的概率)
   = 1 - \prod_{k=1}^N (1 - P_k) = 1 - \prod_{k=1}^N (1 - 1 / (k(k+1)))。

2. 在 N 次取出中，每一次兩個球都是紅色的概率的「前導零」個數。
   所有次都是兩紅的概率 P_all = \prod_{k=1}^N P_k = \prod_{k=1}^N \frac{1}{k(k+1)}。
   我們需要求的是 P_all 在小數點後、第一個非零數字前的零的個數。
   如果 P_all = 0.00...0x...，則零的個數為 \lfloor -\log_{10}(P_all) - \epsilon \rfloor。
   由於 P_all 極小，我們使用 \log_{10}(P_all) = \sum_{k=1}^N \log_{10}(P_k) 來計算。

由於 N 最大為 1,000,000，我們需要預計算這些值以滿足時間限制。
*/

#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

using namespace std;

const int MAXN = 1000005;
double any_prob[MAXN];
double log_all_prob[MAXN];

void precompute() {
    double current_any_not = 1.0;
    double current_log_all = 0.0;
    any_prob[0] = 0;
    log_all_prob[0] = 0;
    for (int k = 1; k < MAXN; ++k) {
        double pk = 1.0 / ((double)k * (k + 1));
        current_any_not *= (1.0 - pk);
        current_log_all += log10(pk);
        any_prob[k] = 1.0 - current_any_not;
        log_all_prob[k] = current_log_all;
    }
}

int main() {
    precompute();
    int n;
    while (cin >> n) {
        cout << fixed << setprecision(6) << any_prob[n] << " " << (int)floor(-log_all_prob[n] - 1e-9) << endl;
    }
    return 0;
}
